// Built-in Themes (spec §3.34, ADR-0050): the maintainer's design system, one Theme per interface accent. Neutrals
// (Radix slate), status colors and shape are shared; only the accent changes. Text keeps at least 4.5:1 contrast
// against the surface it sits on, the main button's label 3:1 or more. Generated from the design system; do not edit
// by hand.
import type { PanelThemeTokens } from './theme.ts'

export interface BuiltinTheme {
  id: string
  name: { en: string; zh: string }
  /** A few colors for the Theme's card in Settings: page, accent tint, main button, dark page. */
  swatches: readonly string[]
  light: PanelThemeTokens
  dark: PanelThemeTokens
}

export const DEFAULT_THEME_ID = 'teal'

/** Built-in Themes that were renamed, and the Theme each became; config and Theme Files naming the old id still work. */
